<style>
.marca-pgc .peca {
  transform-box: fill-box;
}
.marca-pgc .dobra {
  fill: color-mix(in oklab, var(--logo-1) 78%, #000);
}
.marca-pgc .peca-triangulo {
  filter: brightness(0.88);
}
.marca-pgc .peca-pendao {
  transform-origin: 50% 0%;
}
a:hover > .marca-pgc .peca-pendao {
  animation: marca-balanca 0.9s var(--ease-mola);
}
/* Montagem: a onda e a folha entram da esquerda, o capelo desce e o pendão balança. */
.marca-entrada .peca-onda {
  animation: marca-desliza 0.6s var(--ease-saida) 0.05s backwards;
}
.marca-entrada .peca-folha {
  animation: marca-desliza 0.6s var(--ease-saida) 0.15s backwards;
}
.marca-entrada .peca-triangulo {
  animation: marca-aparece 0.5s ease 0.3s backwards;
}
.marca-entrada .peca-capelo {
  transform-origin: 50% 100%;
  animation: marca-desce 0.7s var(--ease-mola) 0.35s backwards;
}
.marca-entrada .peca-pendao {
  animation: marca-aparece 0.2s ease 0.75s backwards, marca-balanca 1.1s var(--ease-mola) 0.75s;
}
@keyframes marca-desliza {
  from { opacity: 0; transform: translateX(-14%); }
}
@keyframes marca-aparece {
  from { opacity: 0; }
}
@keyframes marca-desce {
  from { opacity: 0; transform: translateY(-38%) rotate(-6deg); }
}
@keyframes marca-balanca {
  0% { transform: rotate(0); }
  30% { transform: rotate(-14deg); }
  60% { transform: rotate(8deg); }
  100% { transform: rotate(0); }
}
@media (prefers-reduced-motion: reduce) {
  .marca-pgc .peca {
    animation: none !important;
  }
}
:root.menos-movimento .marca-pgc .peca {
  animation: none !important;
}
</style>
